-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/State.lua
local State = {}
State.__index = State

function State.new(defaults)
    local self = setmetatable({}, State)
    self._listeners = {}
    self._defaults = defaults
    self._maxStatusCharacters = defaults.StatusMaxCharacters or 88
    self._values = {
        selectedTab = defaults.SelectedTab,
        compact = defaults.Compact,
        status = "Hub UI ready; Main Farm is available but disabled.",
        statusKind = "info",
        featureEnabled = {},
    }
    return self
end

function State:GetSnapshot()
    local featureEnabled = {}
    for key, value in pairs(self._values.featureEnabled) do
        featureEnabled[key] = value
    end
    return {
        selectedTab = self._values.selectedTab,
        compact = self._values.compact,
        status = self._values.status,
        statusKind = self._values.statusKind,
        featureEnabled = featureEnabled,
    }
end

function State:_Notify()
    local snapshot = self:GetSnapshot()
    for index = #self._listeners, 1, -1 do
        local listener = self._listeners[index]
        local ok = pcall(listener, snapshot)
        if not ok then
            table.remove(self._listeners, index)
        end
    end
end

function State:Subscribe(listener)
    table.insert(self._listeners, listener)
    local connected = true
    return {
        Disconnect = function()
            if not connected then
                return
            end
            connected = false
            for index = #self._listeners, 1, -1 do
                if self._listeners[index] == listener then
                    table.remove(self._listeners, index)
                    break
                end
            end
        end,
    }
end

function State:SetStatus(message, kind)
    local text = tostring(message)
    if #text > self._maxStatusCharacters then
        text = text:sub(1, self._maxStatusCharacters - 3) .. "..."
    end
    self._values.status = text
    self._values.statusKind = kind or "info"
    self:_Notify()
end

function State:SetSelectedTab(tabName)
    self._values.selectedTab = tabName
    self:_Notify()
end

function State:SetCompact(enabled)
    self._values.compact = enabled == true
    self:_Notify()
end

function State:SetFeatureEnabled(actionId, enabled)
    self._values.featureEnabled[actionId] = enabled == true
    self:_Notify()
end

function State:ResetPresentation()
    self._values.selectedTab = self._defaults.SelectedTab
    self._values.compact = self._defaults.Compact
    self._values.status = "UI presentation settings reset; feature states are unchanged."
    self._values.statusKind = "success"
    self:_Notify()
end

return State
-- END SOURCE: src/ReplicatedStorage/CustomHub/State.lua
end

__bundleFactories["CustomHub.Compatibility"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Compatibility.lua
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local CollectionService = game:GetService("CollectionService")

local Compatibility = {}
Compatibility.__index = Compatibility

function Compatibility.new()
    return setmetatable({
        Player = Players.LocalPlayer,
        ReplicatedStorage = ReplicatedStorage,
        Workspace = Workspace,
        RunService = RunService,
        CollectionService = CollectionService,
    }, Compatibility)
end

function Compatibility:GetPlayerGui()
    if not self.Player then
        return nil, "LocalPlayer is unavailable"
    end
    local playerGui = self.Player:FindFirstChildOfClass("PlayerGui")
    if not playerGui then
        return nil, "PlayerGui is unavailable"
    end
    return playerGui
end

function Compatibility:IsTouchEnabled()
    return UserInputService.TouchEnabled
end

function Compatibility:GetViewportSize()
    local camera = Workspace.CurrentCamera
    if camera then
        return camera.ViewportSize
    end
    return Vector2.new(390, 844)
end

function Compatibility:GetCharacterParts()
    local character = self.Player and self.Player.Character
    if not character then
        return nil, nil, nil
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or not root or humanoid.Health <= 0 then
        return character, humanoid, nil
    end
    return character, humanoid, root
end

function Compatibility:GetQuestModules()
    local questsModule = self.ReplicatedStorage:WaitForChild("Quests", 10)
    local guideModule = self.ReplicatedStorage:WaitForChild("GuideModule", 10)
    if not questsModule or not guideModule then
        return nil, nil, "BNN quest modules are unavailable"
    end

    local ok, quests = pcall(require, questsModule)
    if not ok or type(quests) ~= "table" then
        return nil, nil, "ReplicatedStorage.Quests did not return a quest table"
    end

    local guideOk, guide = pcall(require, guideModule)
    if not guideOk or type(guide) ~= "table" then
        return nil, nil, "GuideModule did not return a data table"
    end
    return quests, guide
end

function Compatibility:GetCommF()
    local remotes = self.ReplicatedStorage:FindFirstChild("Remotes")
    local commF = remotes and remotes:FindFirstChild("CommF_")
    if not commF then
        return nil, "ReplicatedStorage.Remotes.CommF_ is unavailable"
    end
    return commF
end

function Compatibility:GetCombatDependencies()
    local modules = self.ReplicatedStorage:FindFirstChild("Modules")
    local netModule = modules and modules:FindFirstChild("Net")
    local mouseModule = self.ReplicatedStorage:FindFirstChild("Mouse")
    local combatUtilModule = modules and modules:FindFirstChild("CombatUtil")
    if not netModule or not mouseModule or not combatUtilModule then
        return nil, "BNN melee dependency modules are unavailable"
    end

    local registerAttack = netModule:WaitForChild("RE/RegisterAttack", 10)
    if not registerAttack then
        return nil, "Modules.Net.RE/RegisterAttack is unavailable"
    end

    local mouseOk, mouse = pcall(require, mouseModule)
    local combatOk, combatUtil = pcall(require, combatUtilModule)
    local netOk, net = pcall(require, netModule)
    if not mouseOk or not combatOk or not netOk then
        return nil, "BNN melee dependency modules failed to load"
    end

    local hitOk, registerHit = pcall(function()
        return net:RemoteEvent("RegisterHit", true)
    end)
    if not hitOk or not registerHit then
        return nil, "Modules.Net RegisterHit dependency is unavailable"
    end

    return {
        Mouse = mouse,
        CombatUtil = combatUtil,
        Net = net,
        RegisterAttack = registerAttack,
        RegisterHit = registerHit,
    }
end

function Compatibility:IsThirdSea()
    local mapName = self.Workspace:GetAttribute("MAP")
    return mapName == "Sea3"
        or game.PlaceId == 100117331123089
        or game.PlaceId == 7449423635
end

return Compatibility
-- END SOURCE: src/ReplicatedStorage/CustomHub/Compatibility.lua
end

__bundleFactories["CustomHub.FeatureManager"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/FeatureManager.lua
local PlaceholderFeatures = __bundleLoad("CustomHub.Features.PlaceholderFeatures")
local MainFarm = __bundleLoad("CustomHub.Features.MainFarm")

local FeatureManager = {}
FeatureManager.__index = FeatureManager

function FeatureManager.new(state, compatibility, config)
    return setmetatable({
        State = state,
        Modules = { MainFarm, PlaceholderFeatures },
        InitializedModules = {},
        Context = { State = state, Compatibility = compatibility, Config = config },
    }, FeatureManager)
end

function FeatureManager:Initialize()
    for _, featureModule in ipairs(self.Modules) do
        local ok, result = pcall(featureModule.Initialize, featureModule, self.Context)
        if not ok or result == false then
            local message = not ok and result or "Feature module initialization declined"
            self.State:SetStatus("Feature initialization error: " .. tostring(message), "error")
            self:Cleanup()
            return false, tostring(message)
        end
        table.insert(self.InitializedModules, featureModule)
    end
    return true
end

function FeatureManager:Dispatch(actionId, payload)
    if actionId == "settings.compact" then
        self.State:SetCompact(payload == true)
        self.State:SetStatus(
            "Compact layout " .. (payload and "enabled." or "disabled.") .. " (UI only).",
            "success"
        )
        return true
    end

    if actionId == "settings.reset" then
        self.State:ResetPresentation()
        return true
    end

    for _, featureModule in ipairs(self.Modules) do
        local ok, handled = pcall(
            featureModule.Handle,
            featureModule,
            actionId,
            payload,
            self.Context
        )
        if not ok then
            self.State:SetStatus("Action error: " .. tostring(handled), "error")
            return false, tostring(handled)
        end
        if handled then
            return true
        end
    end

    local message = "No UI-shell action registered for " .. tostring(actionId)
    self.State:SetStatus(message, "error")
    return false, message
end

function FeatureManager:Cleanup()
    for index = #self.InitializedModules, 1, -1 do
        local featureModule = self.InitializedModules[index]
        local ok, err = pcall(featureModule.Cleanup, featureModule, self.Context)
        if not ok then
            self.State:SetStatus("Feature cleanup error: " .. tostring(err), "error")
        end
        self.InitializedModules[index] = nil
    end
end

return FeatureManager
-- END SOURCE: src/ReplicatedStorage/CustomHub/FeatureManager.lua
end

__bundleFactories["CustomHub.UI"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/UI.lua
local UI = {}
UI.__index = UI

local function create(className, properties, parent)
    local instance = Instance.new(className)
    for property, value in pairs(properties) do
        instance[property] = value
    end
    instance.Parent = parent
    return instance
end

local function disconnectAll(connections)
    for index = #connections, 1, -1 do
        local connection = connections[index]
        if connection and connection.Connected then
            connection:Disconnect()
        end
        connections[index] = nil
    end
end

function UI.new(playerGui, state, compatibility, config, dispatch, onClose)
    return setmetatable({
        PlayerGui = playerGui,
        State = state,
        Compatibility = compatibility,
        Config = config,
        Dispatch = dispatch,
        OnClose = onClose,
        Gui = nil,
        Root = nil,
        StatusLabel = nil,
        TabButtons = {},
        ToggleLabels = {},
        PersistentConnections = {},
        PageConnections = {},
        StateConnection = nil,
        Scroll = nil,
        Content = nil,
        ContentLayout = nil,
        ActiveTab = nil,
        _contentSizeConnection = nil,
    }, UI)
end

function UI:_Connect(bucket, signal, callback)
    local connection = signal:Connect(callback)
    table.insert(bucket, connection)
    return connection
end

function UI:_ApplySize(snapshot)
    if not self.Root then
        return
    end
    local layout = self.Config.Layout
    local touch = self.Compatibility:IsTouchEnabled()
    local width
    local height
    if snapshot.compact then
        width = touch and layout.MobileWidth or layout.DesktopWidth
        height = touch and layout.MobileHeight or layout.DesktopHeight
    else
        width = layout.ExpandedWidth
        height = layout.ExpandedHeight
    end
    self.Root.Size = UDim2.fromScale(width, height)
end

function UI:_Refresh(snapshot)
    if not self.Gui then
        return
    end

    local theme = self.Config.Theme
    self.StatusLabel.Text = snapshot.status
    if snapshot.statusKind == "error" then
        self.StatusLabel.TextColor3 = theme.Error
    elseif snapshot.statusKind == "success" then
        self.StatusLabel.TextColor3 = theme.Success
    elseif snapshot.statusKind == "warning" then
        self.StatusLabel.TextColor3 = theme.Warning
    else
        self.StatusLabel.TextColor3 = theme.MutedText
    end

    for tabName, button in pairs(self.TabButtons) do
        button.BackgroundColor3 = tabName == snapshot.selectedTab and theme.Selected or theme.Control
        button.TextColor3 = tabName == snapshot.selectedTab and theme.Text or theme.MutedText
    end

    for _, entry in ipairs(self.ToggleLabels) do
        local enabled
        if entry.Control.Kind == "featureToggle" then
            enabled = snapshot.featureEnabled[entry.Control.Action] == true
            entry.Label.Text = enabled and "ON" or "OFF"
        elseif entry.Control.Kind == "settingToggle" then
            enabled = snapshot.compact
            entry.Label.Text = enabled and "On" or "Off"
        end
    end

    self:_ApplySize(snapshot)
    if self.ActiveTab ~= snapshot.selectedTab then
        if self.Config.Pages[snapshot.selectedTab] then
            self:_RenderTab(snapshot.selectedTab)
        else
            self.StatusLabel.Text = "Unknown tab: " .. tostring(snapshot.selectedTab)
            self.StatusLabel.TextColor3 = theme.Error
        end
    end
end

function UI:_ClearPage()
    disconnectAll(self.PageConnections)
    self.ToggleLabels = {}
    for _, child in ipairs(self.Content:GetChildren()) do
        if child ~= self.ContentLayout then
            child:Destroy()
        end
    end
end

function UI:_SelectTab(tabName)
    if not self.Config.Pages[tabName] then
        self.State:SetStatus("Unknown tab: " .. tostring(tabName), "error")
        return false
    end
    self.State:SetSelectedTab(tabName)
    return true
end

function UI:_ActivateControl(control)
    local snapshot = self.State:GetSnapshot()
    if control.Kind == "featureToggle" then
        return self.Dispatch(control.Action, snapshot.featureEnabled[control.Action] ~= true)
    elseif control.Kind == "settingToggle" then
        return self.Dispatch(control.Action, not snapshot.compact)
    end
    return self.Dispatch(control.Action, true)
end

function UI:_AddControl(control)
    local theme = self.Config.Theme
    local layout = self.Config.Layout
    local hasToggle = control.Kind == "featureToggle" or control.Kind == "settingToggle"
    local reservedTitleSpace = hasToggle and (layout.ToggleValueWidth + layout.ToggleGap) or 0
    local row = create("TextButton", {
        Name = "Action_" .. control.Action:gsub("[^%w]", "_"),
        Size = UDim2.new(1, 0, 0, layout.RowHeight),
        BackgroundColor3 = theme.Control,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = "",
        Font = theme.Font,
        TextSize = theme.TextSizes.Control,
        TextColor3 = theme.Text,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = #self.Content:GetChildren(),
    }, self.Content)

    create("UIStroke", {
        Color = theme.Border,
        Thickness = layout.BorderThickness,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, row)

    create("TextLabel", {
        Name = "Title",
        Position = UDim2.fromOffset(layout.RowInset, layout.RowTitleTop),
        Size = UDim2.new(1, -layout.RowInset * 2 - reservedTitleSpace, 0, layout.RowTitleHeight),
        BackgroundTransparency = 1,
        Font = theme.StrongFont,
        Text = control.Label,
        TextColor3 = theme.Text,
        TextSize = theme.TextSizes.Control,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, row)

    create("TextLabel", {
        Name = "Detail",
        Position = UDim2.fromOffset(layout.RowInset, layout.RowDetailTop),
        Size = UDim2.new(1, -layout.RowInset * 2, 0, layout.RowDetailHeight),
        BackgroundTransparency = 1,
        Font = theme.Font,
        Text = control.Detail,
        TextColor3 = theme.MutedText,
        TextSize = theme.TextSizes.Detail,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
    }, row)

    local toggleLabel
    if control.Kind == "featureToggle" or control.Kind == "settingToggle" then
        toggleLabel = create("TextLabel", {
            Name = "Value",
            AnchorPoint = Vector2.new(1, 0),
            Position = UDim2.new(1, -layout.RowInset, 0, layout.ToggleValueTop),
            Size = UDim2.fromOffset(layout.ToggleValueWidth, layout.ToggleValueHeight),
            BackgroundTransparency = 1,
            Font = theme.StrongFont,
            Text = "Off",
            TextColor3 = theme.Accent,
            TextSize = theme.TextSizes.Detail,
            TextXAlignment = Enum.TextXAlignment.Right,
        }, row)
        table.insert(self.ToggleLabels, { Control = control, Label = toggleLabel })
    end

    self:_Connect(self.PageConnections, row.Activated, function()
        self:_ActivateControl(control)
    end)
end

function UI:_RenderTab(tabName)
    local page = self.Config.Pages[tabName]
    if not page then
        return false
    end

    self.ActiveTab = tabName
    self:_ClearPage()
    local theme = self.Config.Theme
    create("TextLabel", {
        Name = "PageDescription",
        Size = UDim2.new(1, 0, 0, self.Config.Layout.PageDescriptionHeight),
        BackgroundTransparency = 1,
        Font = theme.Font,
        Text = page.Description,
        TextColor3 = theme.MutedText,
        TextSize = theme.TextSizes.Body,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        LayoutOrder = 0,
    }, self.Content)

    for _, control in ipairs(page.Controls) do
        self:_AddControl(control)
    end
    self.Scroll.CanvasPosition = Vector2.zero
    self:_Refresh(self.State:GetSnapshot())
    return true
end

function UI:Mount()
    local previous = self.PlayerGui:FindFirstChild("CustomHubShell")
    if previous then
        previous:Destroy()
    end

    local theme = self.Config.Theme
    local layout = self.Config.Layout
    self.Gui = create("ScreenGui", {
        Name = "CustomHubShell",
        ResetOnSpawn = false,
