end

__bundleFactories["CustomHub.Features.Farm.QuestService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
local QuestService = {}
QuestService.__index = QuestService

local excludedQuestNames = {
    BartiloQuest = true,
    Trainees = true,
    MarineQuest = true,
    CitizenQuest = true,
}

function QuestService.new(compatibility)
    local quests, guide, loadError = compatibility:GetQuestModules()
    if not quests then
        return nil, loadError
    end
    return setmetatable({
        Compatibility = compatibility,
        Player = compatibility.Player,
        Quests = quests,
        Guide = guide,
    }, QuestService)
end

function QuestService:GetPlayerLevel()
    local data = self.Player and self.Player:FindFirstChild("Data")
    local level = data and data:FindFirstChild("Level")
    return level and tonumber(level.Value)
end

function QuestService:GetActiveQuestState()
    local guideData = self.Guide and self.Guide.Data
    if type(guideData) ~= "table" then
        return "unknown", nil
    end

    local questData = guideData.QuestData
    if questData == nil then
        return "none", nil
    end
    if type(questData) ~= "table" or type(questData.Task) ~= "table" then
        return "unknown", nil
    end

    local targetName = next(questData.Task)
    if type(targetName) ~= "string" then
        return "active-unknown", nil
    end
    return "active", targetName
end

function QuestService:SelectLevelQuest()
    local level = self:GetPlayerLevel()
    local guideData = self.Guide and self.Guide.Data
    local npcList = guideData and guideData.NPCList
    if not level or type(npcList) ~= "table" then
        return nil, "Player level or GuideModule.Data.NPCList is unavailable"
    end

    local bestLevel = 0
    local bestCandidate = nil
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table" and not excludedQuestNames[npcEntry.InternalQuestName] then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(npcEntry.Levels) == "table" and type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local quest = questGroup[questId]
                    local numericLevel = tonumber(requiredLevel)
                    if type(quest) == "table"
                        and type(quest.Task) == "table"
                        and numericLevel
                        and numericLevel <= level
                        and numericLevel >= bestLevel
                    then
                        local mobName, count = next(quest.Task)
                        local numericCount = tonumber(count)
                        if type(mobName) == "string" and numericCount and numericCount > 1 then
                            bestCandidate = {
                                Level = numericLevel,
                                Name = npcEntry.NPCName,
                                QuestName = npcEntry.InternalQuestName,
                                Pos = npcEntry.Position,
                                Id = questId,
                                Mob = mobName,
                            }

                            local activeState, activeTarget = self:GetActiveQuestState()
                            local numericQuestId = tonumber(questId)
                            if activeState == "active"
                                and activeTarget == mobName
                                and numericQuestId
                                and numericQuestId > 1
                            then
                                local previousQuest = questGroup[numericQuestId - 1]
                                if previousQuest and type(previousQuest.Task) == "table" then
                                    for previousMob, previousCount in pairs(previousQuest.Task) do
                                        if previousMob ~= activeTarget
                                            and tonumber(previousCount)
                                            and tonumber(previousCount) > 1
                                        then
                                            bestCandidate.Mob = previousMob
                                            bestCandidate.Id = numericQuestId - 1
                                            break
                                        end
                                    end
                                end
                            end
                            bestLevel = numericLevel
                        end
                    end
                end
            end
        end
    end

    if not bestCandidate then
        return nil, "No eligible level-based quest candidate"
    end
    return bestCandidate
end

function QuestService:RequestStart(candidate)
    if type(candidate) ~= "table" or not candidate.QuestName or candidate.Id == nil then
        return false, "Quest candidate is incomplete"
    end

    local commF, remoteError = self.Compatibility:GetCommF()
    if not commF then
        return false, remoteError
    end
    local ok, result = pcall(function()
        return commF:InvokeServer("StartQuest", tostring(candidate.QuestName), candidate.Id)
    end)
    if not ok then
        return false, tostring(result)
    end

    -- BNN ignores this return value; acceptance is confirmed separately through QuestData.Task.
    return true, result
end

return QuestService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
end

__bundleFactories["CustomHub.Features.Farm.EnemyService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
local EnemyService = {}
EnemyService.__index = EnemyService

local function normalizeEnemyName(name)
    return (name:gsub(" %p?Lv%.? %d+%p?", ""))
end

function EnemyService.new(compatibility)
    return setmetatable({
        Compatibility = compatibility,
        Workspace = compatibility.Workspace,
        CollisionOriginals = {},
    }, EnemyService)
end

function EnemyService:IsAlive(model)
    if not model or not model.Parent then
        return false
    end
    local root = model:FindFirstChild("HumanoidRootPart")
    local humanoid = model:FindFirstChildWhichIsA("Humanoid")
    return root ~= nil and humanoid ~= nil and humanoid.Health > 0
end

function EnemyService:FindNearest(targetName, origin)
    local enemies = self.Workspace:FindFirstChild("Enemies")
    if not enemies or not targetName or not origin then
        return nil
    end

    local nearest, nearestDistance = nil, math.huge
    for _, enemy in ipairs(enemies:GetChildren()) do
        local matches = type(targetName) == "table"
            and table.find(targetName, enemy.Name) ~= nil
            or enemy.Name == targetName
        if matches and self:IsAlive(enemy) then
            local distance = (enemy.HumanoidRootPart.Position - origin).Magnitude
            if distance < nearestDistance then
                nearest, nearestDistance = enemy, distance
            end
        end
    end
    return nearest, nearestDistance
end

function EnemyService:FindSpawn(targetName)
    local worldOrigin = self.Workspace:FindFirstChild("_WorldOrigin")
    local enemySpawns = worldOrigin and worldOrigin:FindFirstChild("EnemySpawns")
    if not enemySpawns or type(targetName) ~= "string" then
        return nil
    end

    local normalizedTarget = normalizeEnemyName(targetName)
    for _, spawnPart in ipairs(enemySpawns:GetChildren()) do
        if spawnPart:IsA("BasePart") then
            local normalizedSpawn = normalizeEnemyName(spawnPart.Name)
            if spawnPart.Name == targetName or normalizedSpawn == normalizedTarget then
                return spawnPart
            end
        end
    end
    return nil
end

function EnemyService:PrepareTarget(model, playerRoot)
    if not self:IsAlive(model) or not playerRoot then
        return
    end
    if (model.HumanoidRootPart.Position - playerRoot.Position).Magnitude > 50 then
        return
    end

    for _, part in ipairs(model:GetDescendants()) do
        if part:IsA("BasePart") and part.CanCollide then
            self.CollisionOriginals[part] = true
            part.CanCollide = false
        end
    end
end

function EnemyService:RestoreTargetCollision()
    for part, originalCanCollide in pairs(self.CollisionOriginals) do
        if part and part.Parent then
            part.CanCollide = originalCanCollide
        end
        self.CollisionOriginals[part] = nil
    end
end

return EnemyService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
end

__bundleFactories["CustomHub.Features.Farm.MovementService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/MovementService.lua
local MovementService = {}
MovementService.__index = MovementService

local SUBMERGED_REFERENCE = Vector3.new(11538.599609375, -2154.7021484375, 9827.3125)
local SUBMERGED_STAGING = CFrame.new(
    -16269.4082,
    23.9799957,
    1371.66235,
    -0.999388933,
    0,
    -0.0349550731,
    0,
    1,
    0,
    0.0349550731,
    0,
    -0.999388933
)
local TIKI_STAGING = CFrame.new(
    11427.9189,
    -2156.36401,
    9726.24023,
    -0.929097056,
    -7.17796156E-34,
    0.369835705,
    -7.17796156E-34,
    1,
    1.37611875E-34,
    -0.369835705,
    -1.37611875E-34,
    -0.929097056
)

function MovementService.new(compatibility, report)
    return setmetatable({
        Compatibility = compatibility,
        Report = report,
        Active = nil,
        Generation = 0,
        RouteGeneration = 0,
        TagGeneration = 0,
        OwnsTeleportTag = false,
        LastRouteRequest = {},
    }, MovementService)
end

function MovementService:_GetRoute(destination, currentPosition)
    if not self.Compatibility:IsThirdSea() then
        return nil
    end

    local destinationDistance = (destination.Position - SUBMERGED_REFERENCE).Magnitude
    local currentDistance = (currentPosition - SUBMERGED_REFERENCE).Magnitude
    if destinationDistance <= 3000 and currentDistance > 3000 then
        return { Name = "Submerged", Stage = SUBMERGED_STAGING }
    end
    if destinationDistance > 3000 and currentDistance <= 3000 then
        return { Name = "Tiki", Stage = TIKI_STAGING }
    end
    return nil
end

function MovementService:_RestoreCollision(active)
    for part, canCollide in pairs(active.CollisionOriginals) do
        if part and part.Parent then
            part.CanCollide = canCollide
        end
        active.CollisionOriginals[part] = nil
    end
end

function MovementService:_Finish(active, delayTagRemoval)
    if self.Active ~= active then
        return
    end
    self.Active = nil
    if active.Connection and active.Connection.Connected then
        active.Connection:Disconnect()
    end
    self:_RestoreCollision(active)

    if active.FloatForce and active.FloatForce.Parent then
        active.FloatForce:Destroy()
    end
    if active.Humanoid and active.Humanoid.Parent then
        active.Humanoid.PlatformStand = false
    end

    if active.HasTeleportTag then
        local tagGeneration = self.TagGeneration
        local function removeTag()
            if self.Active == nil
                and self.TagGeneration == tagGeneration
                and self.Compatibility.CollectionService:HasTag(self.Compatibility.Player, "Teleporting")
            then
                self.Compatibility.CollectionService:RemoveTag(self.Compatibility.Player, "Teleporting")
                self.OwnsTeleportTag = false
            end
        end
        if delayTagRemoval then
            task.delay(1.5, removeTag)
        else
            removeTag()
        end
    end
end

function MovementService:_StopMovement()
    self.Generation += 1
    local active = self.Active
    if active then
        self:_Finish(active, true)
    end
end

function MovementService:Cancel()
    self.RouteGeneration += 1
    self:_StopMovement()
end

function MovementService:_RequestRoute(route, isCurrent, routeGeneration)
    local now = os.clock()
    if now - (self.LastRouteRequest[route.Name] or 0) < 5 then
        return false, "Travel request is cooling down"
    end
    self.LastRouteRequest[route.Name] = now

    task.spawn(function()
        if not isCurrent() or self.RouteGeneration ~= routeGeneration then
            return
        end
        local replication = self.Compatibility.ReplicatedStorage
        local modules = replication:FindFirstChild("Modules")
        local netContainer = modules and modules:FindFirstChild("Net")
        local commF, commFError = self.Compatibility:GetCommF()
        if not netContainer or not commF then
            self.Report("Travel dependencies are unavailable", "error")
            return
        end

        local ok, err = pcall(function()
            if route.Name == "Submerged" then
                local remote = netContainer:FindFirstChild("RF/SubmarineWorkerSpeak")
                if not remote then
                    error("Modules.Net.RF/SubmarineWorkerSpeak is unavailable")
                end
                remote:InvokeServer("TravelToSubmergedIsland")
                if isCurrent() and self.RouteGeneration == routeGeneration then
                    commF:InvokeServer("SetLastSpawnPoint", "SubmergedIsland")
                end
            else
                local remote = netContainer:FindFirstChild("RF/SubmarineTransportation")
                if not remote then
                    error("Modules.Net.RF/SubmarineTransportation is unavailable")
                end
                remote:InvokeServer("GetAvailableLocations")
                if isCurrent() and self.RouteGeneration == routeGeneration then
                    remote:InvokeServer("InitiateTeleport", "Tiki Outpost")
                end
            end
        end)
        if not isCurrent() or self.RouteGeneration ~= routeGeneration then
            return
        end
        if ok then
            self.Report(route.Name .. " travel request submitted", "info")
        else
            self.Report("Travel request error: " .. tostring(err), "error")
        end
    end)
    return true
end

function MovementService:MoveTo(destination, options)
    options = options or {}
    if typeof(destination) ~= "CFrame" then
        return false, "Movement destination must be a CFrame"
    end

    local character, humanoid, root = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        return false, "Character is unavailable"
    end
    if self.LastStallAt and os.clock() - self.LastStallAt < 1 then
        return false, "Movement retry cooldown after a stall"
    end

    local route = self:_GetRoute(destination, root.Position)
    local goal = route and route.Stage or destination
    local threshold = route and 8 or (tonumber(options.Threshold) or 2.5)
    local isCurrent = options.IsCurrent or function()
        return true
    end

    local active = self.Active
    if active
        and active.Character == character
        and active.RouteName == (route and route.Name)
        and (active.Goal.Position - goal.Position).Magnitude <= 12
    then
        return true, "already moving"
    end

    self:_StopMovement()
    if (goal.Position - root.Position).Magnitude <= threshold then
        if route then
            local requested, requestError = self:_RequestRoute(
                route,
                isCurrent,
                self.RouteGeneration
            )
            return requested, requestError or "at travel staging point"
        end
        root.CFrame = destination
        return true, "arrived"
    end

    self.Generation += 1
    self.TagGeneration += 1
    local generation = self.Generation
    local collisionOriginals = {}
    for _, descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("BasePart") then
            collisionOriginals[descendant] = descendant.CanCollide
            descendant.CanCollide = false
        end
    end

    local floatForce = root:FindFirstChild("FloatForce")
    local ownsFloatForce = false
    if not floatForce then
        floatForce = Instance.new("BodyVelocity")
        floatForce.Name = "FloatForce"
        floatForce.Velocity = Vector3.zero
        floatForce.MaxForce = Vector3.new(100000, 100000, 100000)
        floatForce.P = 10000
        floatForce.Parent = root
        ownsFloatForce = true
    end

    local hasTag = self.Compatibility.CollectionService:HasTag(
        self.Compatibility.Player,
        "Teleporting"
    )
    if not hasTag then
        self.Compatibility.CollectionService:AddTag(self.Compatibility.Player, "Teleporting")
        self.OwnsTeleportTag = true
    end

    active = {
        Character = character,
        Humanoid = humanoid,
        Root = root,
        Goal = goal,
        RouteName = route and route.Name,
        Route = route,
        Threshold = threshold,
        Speed = route and 190 or (tonumber(options.Speed) or 300),
        IsCurrent = isCurrent,
        Generation = generation,
        CollisionOriginals = collisionOriginals,
        FloatForce = ownsFloatForce and floatForce or nil,
        HasTeleportTag = self.OwnsTeleportTag,
        BestDistance = (goal.Position - root.Position).Magnitude,
        LastProgressAt = os.clock(),
    }
    self.Active = active

    active.Connection = self.Compatibility.RunService.Heartbeat:Connect(function(deltaTime)
        if self.Active ~= active or self.Generation ~= generation or not isCurrent() then
            self:_Finish(active, true)
            return
        end

        local currentCharacter, currentHumanoid, currentRoot = self.Compatibility:GetCharacterParts()
        if currentCharacter ~= character
            or currentHumanoid ~= humanoid
            or currentRoot ~= root
            or root.Anchored
        then
            self.LastStallAt = os.clock()
            self:_Finish(active, true)
            self.Report("Movement interrupted by character replacement or an anchored root", "warning")
            return
        end

        local offset = goal.Position - root.Position
        local distance = offset.Magnitude
        if distance <= threshold then
            root.CFrame = goal
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            self:_Finish(active, true)
            if route then
                self:_RequestRoute(route, isCurrent, self.RouteGeneration)
            end
            return
        end
        if distance < active.BestDistance - 1 then
            active.BestDistance = distance
            active.LastProgressAt = os.clock()
        elseif os.clock() - active.LastProgressAt > 2.5 then
            self.LastStallAt = os.clock()
            self:_Finish(active, true)
            self.Report("Movement stalled; cancelling this attempt before retry", "warning")
            return
        end

        local step = math.min(active.Speed * deltaTime, 18)
        if step <= 0 then
            return
        end
        local nextPosition = root.Position + offset.Unit * math.min(step, distance)
        root.CFrame = CFrame.new(nextPosition)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)

    return true, route and ("moving to " .. route.Name .. " staging") or "moving"
end

return MovementService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/MovementService.lua
end

__bundleFactories["CustomHub.Features.Farm.CombatService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/CombatService.lua
local CombatService = {}
CombatService.__index = CombatService

local validHitPartNames = {
    RightUpperArm = true,
    RightLowerArm = true,
    RightHand = true,
    RightUpperLeg = true,
    RightLowerLeg = true,
    RightFoot = true,
    LeftUpperArm = true,
    LeftLowerArm = true,
    LeftHand = true,
    LeftUpperLeg = true,
    LeftLowerLeg = true,
    LeftFoot = true,
    UpperTorso = true,
    LowerTorso = true,
    Head = true,
}

function CombatService.new(compatibility, enemyService)
    local dependencies, dependencyError = compatibility:GetCombatDependencies()
    if not dependencies then
        return nil, dependencyError
    end
    return setmetatable({
        Compatibility = compatibility,
        EnemyService = enemyService,
        Dependencies = dependencies,
        AttackIndex = 0,
        AttackGeneration = 0,
        AttackBusy = false,
    }, CombatService)
end

function CombatService:FindWeapon(category)
    local player = self.Compatibility.Player
    local backpack = player and player:FindFirstChild("Backpack")
    local character = player and player.Character
    if backpack then
        for _, item in ipairs(backpack:GetChildren()) do
            if item:IsA("Tool") and item.ToolTip == category then
                return item
            end
        end
    end
    if character then
        for _, item in ipairs(character:GetChildren()) do
            if item:IsA("Tool") and item.ToolTip == category then
                return item
            end
        end
    end
    return nil
end

function CombatService:EquipWeapon(category)
    local tool = self:FindWeapon(category)
    if not tool then
        return false, "No owned " .. tostring(category) .. " tool was found"
    end

    local character, humanoid = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or humanoid.Sit then
        return false, "Character cannot equip a tool"
    end
    if tool.Parent ~= character then
        humanoid:EquipTool(tool)
    end
    if tool.Parent ~= character then
        return false, "Selected tool did not equip"
    end
    return true, tool
end

function CombatService:_FindBladeHitParts(character, root, range)
    local enemies = self.Compatibility.Workspace:FindFirstChild("Enemies")
    if not enemies then
        return {}
    end

    local parts = {}
    for _, model in ipairs(enemies:GetChildren()) do
        if model ~= character and model:IsDescendantOf(self.Compatibility.Workspace) then
            local targetRoot = model:FindFirstChild("HumanoidRootPart")
            if targetRoot then
                local effectiveRange = range
                local points = { targetRoot.Position }
                if targetRoot.Size.Y > 5 then
                    table.insert(
                        points,
                        (targetRoot.CFrame * CFrame.new(0, -targetRoot.Size.Y * 1.5 + 3, 0)).Position
                    )
                end

                for _, point in ipairs(points) do
                    if (point - root.Position).Magnitude < 10 + effectiveRange + targetRoot.Size.X / 2 then
                        for _, part in ipairs(model:GetChildren()) do
                            if part:IsA("BasePart")
                                and (part.Position - root.Position).Magnitude
                                    <= effectiveRange + targetRoot.Size.X / 2
                            then
                                table.insert(parts, part)
                            end
                        end
                        break
                    end
                end
            end
        end
    end
    return parts
end

function CombatService:_GetAttackCandidates(character, root, range)
    local combatUtil = self.Dependencies.CombatUtil
    local candidates, seenRigs = {}, {}
    for _, hitPart in ipairs(self:_FindBladeHitParts(character, root, range)) do
        local rig = combatUtil:GetRigOfHitPart(hitPart)
        if rig and not seenRigs[rig] and validHitPartNames[hitPart.Name] and combatUtil:IsVulnerable(rig) then
            local summoner = rig:FindFirstChild("Summoner")
            local ownSummoner = character:FindFirstChild("Summoner")
            local ownSummonerCharacter = ownSummoner and ownSummoner.Value
            local allowed = rig ~= character
                and (not ownSummonerCharacter or rig ~= ownSummonerCharacter.Character)
                and (not summoner
                    or summoner.Value ~= game:GetService("Players"):GetPlayerFromCharacter(character))
            if allowed then
                table.insert(candidates, { rig, hitPart })
                seenRigs[rig] = true
            end
        end
    end
    return candidates
end

function CombatService:AttackM1(target, range, weaponCategory)
    local character, humanoid, root = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or not root or not self.EnemyService:IsAlive(target) then
        return false, "Target or character is invalid"
    end

    local targetRoot = target:FindFirstChild("HumanoidRootPart")
    if not targetRoot or (root.Position - targetRoot.Position).Magnitude >= 70 then
        return false, "Target is outside ClickM1 range"
    end

    local tool = character:FindFirstChildOfClass("Tool")
    if not tool or tool.ToolTip ~= (weaponCategory or "Melee") then
        return false, "Selected weapon category is not equipped"
    end
    local stun = character:FindFirstChild("Stun")
    if not stun or stun.Value ~= 0 then
        return false, "Character is stunned or has no Stun state"
    end
    if self.AttackBusy then
        return false, "M1 animation cooldown"
    end

    local candidates = self:_GetAttackCandidates(character, root, tonumber(range) or 30)
    if #candidates == 0 then
        return false, "No valid hit parts in BNN attack range"
    end

    local combatUtil = self.Dependencies.CombatUtil
    local animationCache = combatUtil:GetMovesetAnimCache(humanoid)
    local weaponName = combatUtil:GetWeaponName(tool)
    local weaponData = combatUtil:GetWeaponData(weaponName)
    if not animationCache or not weaponData or not weaponData.Moveset or not weaponData.Moveset.Basic then
        return false, "CombatUtil weapon or moveset data is unavailable"
    end

    local weaponType = weaponData.WeaponType
    if not combatUtil:CanAttack(character, weaponType) then
        return false, "CombatUtil rejected attack timing"
    end

    local basics = weaponData.Moveset.Basic
    if #basics == 0 then
        return false, "Weapon has no basic attack animations"
    end
    self.AttackIndex = self.AttackIndex % #basics + 1

    local pureWeaponName = combatUtil:GetPureWeaponName(weaponName)
    local animation = animationCache[pureWeaponName .. "-basic" .. self.AttackIndex]
    if not animation then
        return false, "Basic attack animation is not cached"
    end

    local speedMultiplier = animation:GetAttribute("SpeedMult") or 1
    if speedMultiplier <= 0 then
        speedMultiplier = 1
    end
    local duration = animation.Length / speedMultiplier
    local hitPart = table.remove(candidates, 1)[2]

    self.Dependencies.RegisterAttack:FireServer(duration)
    self.Dependencies.RegisterHit:FireServer(hitPart, candidates)
    animation:Play(0.1, 1, speedMultiplier)

    self.AttackBusy = true
    self.AttackGeneration += 1
    local generation = self.AttackGeneration
    task.delay(duration, function()
        if self.AttackGeneration == generation then
            self.AttackBusy = false
        end
    end)
    return true, "M1 request issued"
end

function CombatService:Cancel()
    self.AttackGeneration += 1
    self.AttackBusy = false
end

return CombatService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/CombatService.lua
end

__bundleFactories["CustomHub.Features.MainFarm"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/MainFarm.lua
local QuestService = __bundleLoad("CustomHub.Features.Farm.QuestService")
local EnemyService = __bundleLoad("CustomHub.Features.Farm.EnemyService")
local MovementService = __bundleLoad("CustomHub.Features.Farm.MovementService")
local CombatService = __bundleLoad("CustomHub.Features.Farm.CombatService")

local MainFarm = {
    Running = false,
    Session = 0,
    Context = nil,
}

local function questKey(candidate)
    return tostring(candidate.QuestName) .. ":" .. tostring(candidate.Id)
end

function MainFarm:_SetStatus(message, kind)
    local now = os.clock()
    if self.LastStatus == message and now - (self.LastStatusAt or 0) < 1.5 then
        return
    end
    self.LastStatus = message
    self.LastStatusAt = now
    if self.Context and self.Context.State then
        self.Context.State:SetStatus(message, kind)
    end
end

function MainFarm:_EnsureBaseServices()
    if self.QuestService and self.EnemyService and self.MovementService then
        return true
    end

    local context = self.Context
    if not context or not context.Compatibility then
        return false, "Hub compatibility adapter is unavailable"
    end

    local questService, questError = QuestService.new(context.Compatibility)
    if not questService then
        return false, questError
    end
    self.QuestService = questService
    self.EnemyService = EnemyService.new(context.Compatibility)
    self.MovementService = MovementService.new(context.Compatibility, function(message, kind)
        self:_SetStatus(message, kind)
    end)
    return true
end

function MainFarm:_EnsureCombatService()
    if self.CombatService then
        return true
    end
    if self.CombatDependencyAttempted then
        if os.clock() - (self.LastCombatDependencyAttemptAt or 0) < 5 then
            return false, self.CombatDependencyError
        end
    end
    self.CombatDependencyAttempted = true
    self.LastCombatDependencyAttemptAt = os.clock()
    local combatService, combatError = CombatService.new(
        self.Context.Compatibility,
        self.EnemyService
    )
    if not combatService then
        self.CombatDependencyError = combatError
        return false, combatError
    end
    self.CombatService = combatService
    return true
end

function MainFarm:_IsCurrent(session)
    return self.Running and self.Session == session
end

function MainFarm:_MoveTo(destination, session, threshold)
    if not self.MovementService then
        return false
    end
    return self.MovementService:MoveTo(destination, {
        Speed = 190,
        Threshold = threshold,
        IsCurrent = function()
            return self:_IsCurrent(session)
        end,
    })
end

function MainFarm:_ClearTarget()
    local hadTarget = self.Target ~= nil or self.TargetName ~= nil
    if hadTarget then
        if self.EnemyService then
            self.EnemyService:RestoreTargetCollision()
        end
        if self.MovementService then
            self.MovementService:Cancel()
        end
    end
    self.Target = nil
    self.TargetName = nil
end

function MainFarm:_RequestQuest(candidate, session)
    local key = questKey(candidate)
    local now = os.clock()
    if self.LastQuestAttemptKey == key and now - (self.LastQuestAttemptAt or 0) < 8 then
        self:_SetStatus("Waiting for active quest confirmation", "warning")
        return
    end

    self.LastQuestAttemptKey = key
    self.LastQuestAttemptAt = now
    local requested, result = self.QuestService:RequestStart(candidate)
    if not self:_IsCurrent(session) then
        return
    end
    if requested then
        self:_SetStatus(
            "Quest request sent; waiting for GuideModule.Data.QuestData.Task confirmation",
            "warning"
        )
    else
        self:_SetStatus("Quest request failed: " .. tostring(result), "error")
    end
end

function MainFarm:_Step(session)
    if not self:_IsCurrent(session) then
        return
    end

    local compatibility = self.Context.Compatibility
    local character, humanoid, root = compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        if self.MovementService then
            self.MovementService:Cancel()
        end
        self:_ClearTarget()
        self:_SetStatus("Waiting for a living character and HumanoidRootPart", "warning")
        return
    end

    if self.Character ~= character then
        if self.MovementService then
            self.MovementService:Cancel()
        end
        if self.EnemyService then
            self.EnemyService:RestoreTargetCollision()
        end
        self.Character = character
        self.Target = nil
        self.TargetName = nil
        self:_SetStatus("Character ready; reacquiring farm state", "info")
    end

    local questState, activeTarget = self.QuestService:GetActiveQuestState()
    if questState == "unknown" then
        self:_ClearTarget()
        self.MovementService:Cancel()
        self:_SetStatus(
            "Waiting: GuideModule.Data quest state is unavailable; quest is not assumed active",
            "warning"
        )
        return
    elseif questState == "active-unknown" then
        self:_ClearTarget()
        self.MovementService:Cancel()
        self:_SetStatus("Waiting: an active quest exists but its target is not exposed", "warning")
        return
    elseif questState == "none" then
        self:_ClearTarget()
        local candidate, selectionError = self.QuestService:SelectLevelQuest()
        if not candidate then
            self.MovementService:Cancel()
            self:_SetStatus("Quest selection unavailable: " .. tostring(selectionError), "error")
            return
        end

        local giverPosition = candidate.Pos
        if typeof(giverPosition) ~= "Vector3" and typeof(giverPosition) ~= "CFrame" then
            self.MovementService:Cancel()
            self:_SetStatus("Selected quest giver has no usable position", "error")
            return
        end
        local candidateKey = questKey(candidate)
        if self.PendingQuestKey ~= candidateKey then
            if self.PendingQuestKey and self.MovementService then
                self.MovementService:Cancel()
            end
            self.PendingQuestKey = candidateKey
            self.PendingQuestReachedAt = nil
        end
        local giverCFrame = typeof(giverPosition) == "CFrame"
            and giverPosition
            or CFrame.new(giverPosition)
        if (root.Position - giverCFrame.Position).Magnitude > 8 then
            self.PendingQuestReachedAt = nil
            self:_MoveTo(giverCFrame * CFrame.new(0, 4, 2), session, 8)
            self:_SetStatus("Approaching quest giver: " .. tostring(candidate.Name), "info")
            return
        end
        if not self.PendingQuestReachedAt then
            self.PendingQuestReachedAt = os.clock()
            self:_SetStatus("At quest giver; waiting before quest request", "info")
            return
        elseif os.clock() - self.PendingQuestReachedAt < 2 then
            return
        end
        self:_RequestQuest(candidate, session)
        return
    end

    if self.TargetName ~= activeTarget then
        self:_ClearTarget()
        self.TargetName = activeTarget
    end

    local target = self.EnemyService:FindNearest(activeTarget, root.Position)
    if not target then
        if self.Target then
            self:_ClearTarget()
        end
        local spawnPart = self.EnemyService:FindSpawn(activeTarget)
        if spawnPart then
            self:_MoveTo(spawnPart.CFrame * CFrame.new(0, 60, 0), session, 100)
            self:_SetStatus("Waiting near supported spawn: " .. activeTarget, "info")
        else
            self.MovementService:Cancel()
            self:_SetStatus(
                "Waiting for living " .. activeTarget .. " or a Workspace._WorldOrigin.EnemySpawns marker",
                "warning"
            )
        end
        return
    end

    if self.Target ~= target then
        self:_ClearTarget()
        self.Target = target
        self.TargetName = activeTarget
        self:_SetStatus("Target acquired: " .. activeTarget, "success")
    end
    if not self.EnemyService:IsAlive(target) then
        self:_ClearTarget()
        self:_SetStatus("Target died or became invalid; reacquiring", "info")
        return
    end

    self.EnemyService:PrepareTarget(target, root)
    local combatReady, combatError = self:_EnsureCombatService()
    if combatReady then
        local farmSettings = self.Context.Config and self.Context.Config.FarmSettings
        local weaponCategory = farmSettings and farmSettings.WeaponCategory or "Melee"
        if weaponCategory == "Blox Fruit" then
            self:_SetStatus("Blox Fruit M1 is a separate BNN path and is not part of this batch", "warning")
        else
            local equipped, equipResult = self.CombatService:EquipWeapon(weaponCategory)
            if equipped then
                local attackIssued, attackResult = self.CombatService:AttackM1(
                    target,
                    30,
                    weaponCategory
                )
                if attackIssued then
                    self:_SetStatus("M1 request issued; server damage is not yet confirmed", "info")
                elseif attackResult ~= "M1 animation cooldown" then
                    self:_SetStatus("Combat waiting: " .. tostring(attackResult), "warning")
                end
            else
                self:_SetStatus("Combat waiting: " .. tostring(equipResult), "warning")
            end
        end
    else
        self:_SetStatus("Combat dependencies unavailable: " .. tostring(combatError), "error")
    end

    if self.EnemyService:IsAlive(target) then
        local targetRoot = target:FindFirstChild("HumanoidRootPart")
        if targetRoot then
            self:_MoveTo(targetRoot.CFrame * CFrame.new(7, 20, 0), session, 2.5)
            if (root.Position - targetRoot.Position).Magnitude >= 30 then
                self:_SetStatus("Approaching target: " .. activeTarget, "info")
            end
        end
    else
        self:_ClearTarget()
        self:_SetStatus("Target died or became invalid; reacquiring", "info")
    end
end

function MainFarm:_Run(session)
    while self:_IsCurrent(session) do
        local ok, err = pcall(self._Step, self, session)
        if not ok then
            if self.MovementService then
                self.MovementService:Cancel()
            end
            self:_SetStatus("Main Farm step error: " .. tostring(err), "error")
        end
        task.wait(0.15)
    end
end

function MainFarm:Initialize(context)
    self.Context = context
    self.Running = false
    self.Session += 1
    self.Character = nil
    self.Target = nil
    self.TargetName = nil
    self.QuestService = nil
    self.EnemyService = nil
    self.MovementService = nil
    self.CombatService = nil
    self.CombatDependencyAttempted = false
    self.CombatDependencyError = nil
    self.LastQuestAttemptKey = nil
    self.LastQuestAttemptAt = 0
    self.LastStatus = nil

    local player = context.Compatibility.Player
    if player then
        self.CharacterAddedConnection = player.CharacterAdded:Connect(function()
            if self.MovementService then
                self.MovementService:Cancel()
            end
            if self.EnemyService then
                self.EnemyService:RestoreTargetCollision()
            end
            if self.CombatService then
                self.CombatService:Cancel()
            end
            self.Target = nil
            self.TargetName = nil
            self.Character = nil
            self:_SetStatus("Character changed; farm session will reacquire after respawn", "warning")
        end)
        self.CharacterRemovingConnection = player.CharacterRemoving:Connect(function()
            if self.MovementService then
                self.MovementService:Cancel()
            end
            if self.CombatService then
                self.CombatService:Cancel()
            end
            self:_ClearTarget()
        end)
    end
    return true
end

function MainFarm:Start()
    if self.Running then
        return true
    end
    local ready, setupError = self:_EnsureBaseServices()
    if not ready then
        self:_SetStatus("Main Farm unavailable: " .. tostring(setupError), "error")
        return false, setupError
    end

    self.Session += 1
    self.Running = true
    self.CombatDependencyAttempted = false
    self.CombatDependencyError = nil
    local session = self.Session
    self.Context.State:SetFeatureEnabled("farm.main", true)
    self:_SetStatus("Main Farm enabled; reading authoritative quest state", "success")
    task.spawn(self._Run, self, session)
    return true
end

function MainFarm:Stop()
    self.Session += 1
    self.Running = false
    if self.MovementService then
        self.MovementService:Cancel()
    end
    if self.CombatService then
        self.CombatService:Cancel()
    end
    if self.EnemyService then
        self.EnemyService:RestoreTargetCollision()
    end
    self.Target = nil
    self.TargetName = nil
    self.PendingQuestKey = nil
    self.PendingQuestReachedAt = nil
    if self.Context and self.Context.State then
        self.Context.State:SetFeatureEnabled("farm.main", false)
    end
end

function MainFarm:Handle(actionId, payload)
    if actionId ~= "farm.main" then
        return false
    end
    if payload == true then
        self:Start()
    else
        self:Stop()
        self:_SetStatus("Main Farm stopped; movement and attack loop cancelled", "info")
    end
    return true
end

function MainFarm:Cleanup()
    self:Stop()
    if self.CharacterAddedConnection then
        self.CharacterAddedConnection:Disconnect()
        self.CharacterAddedConnection = nil
    end
    if self.CharacterRemovingConnection then
        self.CharacterRemovingConnection:Disconnect()
        self.CharacterRemovingConnection = nil
    end
    self.QuestService = nil
    self.EnemyService = nil
    self.MovementService = nil
    self.CombatService = nil
    self.Context = nil
    return true
end

return MainFarm
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/MainFarm.lua
end

__bundleFactories["CustomHub"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/init.lua
local Config = __bundleLoad("CustomHub.Config")
local State = __bundleLoad("CustomHub.State")
local Compatibility = __bundleLoad("CustomHub.Compatibility")
local FeatureManager = __bundleLoad("CustomHub.FeatureManager")
local UI = __bundleLoad("CustomHub.UI")

local Hub = {}
Hub.__index = Hub
local activeHub = nil

function Hub.new()
    local state = State.new(Config.Defaults)
    local compatibility = Compatibility.new()
    local featureManager = FeatureManager.new(state, compatibility, Config)

    return setmetatable({
        State = state,
        Compatibility = compatibility,
        FeatureManager = featureManager,
        UI = nil,
        Started = false,
        Destroying = false,
    }, Hub)
end

function Hub:Start()
    if self.Started then
        return true
    end

    local playerGui, playerGuiError = self.Compatibility:GetPlayerGui()
    if not playerGui then
        self.State:SetStatus(playerGuiError, "error")
        return false, playerGuiError
    end

    if activeHub and activeHub ~= self then
        activeHub:Destroy()
    end

    local initialized, initError = self.FeatureManager:Initialize()
    if not initialized then
        self.State:SetStatus("Feature setup error: " .. tostring(initError), "error")
        return false, initError
    end

    self.UI = UI.new(
        playerGui,
        self.State,
        self.Compatibility,
        Config,
        function(actionId, payload)
            return self.FeatureManager:Dispatch(actionId, payload)
        end,
        function()
            self:Destroy()
        end
    )

    local mounted, mountError = pcall(function()
        self.UI:Mount()
    end)
    if not mounted then
        self.UI:Destroy()
        self.UI = nil
        self.FeatureManager:Cleanup()
        self.State:SetStatus("UI mount error: " .. tostring(mountError), "error")
        return false, tostring(mountError)
    end

    self.Started = true
    activeHub = self
    self.State:SetStatus("Hub UI ready; Main Farm is available but disabled.", "success")
    return true
end

function Hub:Destroy()
    if self.Destroying then
        return
    end
    self.Destroying = true

    if self.UI then
        self.UI:Destroy()
        self.UI = nil
    end
    self.FeatureManager:Cleanup()
    self.Started = false
    if activeHub == self then
        activeHub = nil
    end
    self.State:SetStatus("Hub UI closed; feature cleanup completed.", "info")
    self.Destroying = false
end

return Hub
-- END SOURCE: src/ReplicatedStorage/CustomHub/init.lua
end

-- BEGIN BUNDLED CLIENT ENTRYPOINT
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CustomHub = __bundleLoad("CustomHub")

local hub = CustomHub.new()
local started, startError = hub:Start()
if not started then
    warn("[CustomHub] " .. tostring(startError))
end

script.Destroying:Connect(function()
    hub:Destroy()
end)
-- END BUNDLED CLIENT ENTRYPOINT
